    companyWebsite: companyWebsite,
    companyLinkedinUrl: liUrl,
    companyEmployeesCount: Number(companyEmployeesCount) || 0,
    companyDescription: companyDescription,
    location: location,
    country: country,
    jobOpeningTitle: jobOpeningTitle,
    acquiringCompanyName: acquiringCompanyName,
    link: link,
    postedAt: postedAt,
    personFullName: personFullName,
    personJobTitle: personJobTitle,
    personLinkedinUrl: personLinkedinUrl,
    title: jobOpeningTitle,
  }});
}
return out;

